-- v811 remaining authored trames 018–020, guarded and order-preserving.
WITH edits(scenario_id,variant_id,field,ord,old_title,old_text,new_title,new_text) AS (VALUES
('018','A','v540_runtime_trames',1,'Des visites séparées','Plusieurs personnes sont entrées dans le foyer, mais les registres ne montrent aucune réunion des neuf anciens pensionnaires. La présence de neuf noms ne prouve donc pas une action collective.','VISITES SÉPARÉES','Les registres montrent des visites séparées au foyer. Ils ne prouvent pas que les neuf anciens résidents étaient réunis.'),
('018','A','v540_runtime_trames',2,'La table a été dressée après les violences','Des traces de lutte se trouvent sous la nappe. La vaisselle a été placée après le désordre : il faut identifier qui a modifié la scène.','TABLE DRESSÉE APRÈS LA LUTTE','Des traces de lutte se trouvent sous la nappe. La table a été dressée après la confrontation.'),
('018','A','v540_runtime_trames',3,'Deux arrivées à des moments différents','Un ancien résident revient plus tard, alors que les assiettes sont déjà disposées. Les horaires permettent de distinguer celui qui les a placées de celui qui les a découvertes.','UN RETOUR PLUS TARDIF','Un ancien résident revient quand la table est déjà dressée. Ce retour ne prouve pas qu’il a placé les assiettes.'),
('018','B','v540_runtime_trames',1,'Une menace ne suffit pas à prouver le meurtre','Un ancien pensionnaire s''est disputé avec le directeur et l''a menacé. D''autres passages ont suivi : il faut distinguer ces rencontres.','MENACE, PUIS AUTRES PASSAGES','Un ancien résident a menacé le directeur. D’autres personnes sont passées ensuite, sans preuve que cette menace ait mené au meurtre.'),
('018','B','v540_runtime_trames',2,'Les comptes du foyer attirent l''attention','Des documents financiers ont été manipulés près de la période du décès. Le passé du foyer explique la colère, mais pas encore la dernière confrontation.','COMPTES MODIFIÉS','Des documents comptables ont été manipulés autour du décès. Le passé du foyer explique des tensions, pas l’auteur de la dernière altercation.'),
('018','B','v540_runtime_trames',3,'Les assiettes ont été placées après la mort','La disposition des neuf assiettes appartient à une intervention ultérieure. Cette mise en scène ne permet pas, à elle seule, d''identifier celui qui a tué.','ASSIETTES PLACÉES APRÈS LA MORT','Les neuf assiettes ont été disposées après la mort. Leur présence ne permet pas d’identifier le meurtrier.'),
('018','C','v540_runtime_trames',1,'Un projet de confrontation, pas un ordre de tuer','Deux anciens résidents voulaient intimider le directeur pour évoquer les sanctions passées. Les premiers messages n''établissent pas de projet de meurtre.','PROJET D’INTIMIDATION','Deux anciens résidents voulaient intimider le directeur à propos d’anciennes sanctions. Aucun message ne montre qu’ils voulaient le tuer.'),
('018','C','v540_runtime_trames',2,'Les deux anciens résidents ne sont pas arrivés ensemble','Les relevés placent leurs arrivées à des moments différents. Les traces de lutte doivent être distinguées de celles laissées lors de la mise en scène.','ARRIVÉES À DES HEURES DIFFÉRENTES','Les deux anciens résidents sont arrivés à des heures différentes. Certaines traces viennent de la lutte, d’autres de la mise en scène.'),
('018','C','v540_runtime_trames',3,'Les neuf assiettes apparaissent après le décès','Une personne a disposé les assiettes après la lutte. Le symbole peut renvoyer au projet d''intimidation, sans prouver une décision commune de tuer.','ASSIETTES APRÈS LA LUTTE','Les assiettes ont été disposées après la lutte. Le projet d’intimidation ne prouve pas une décision commune de tuer.'),
('019','A','v570_runtime_trames',1,'Deux dossiers financiers différents','La victime préparait une version publique de ses accusations et une version complète pour les contrôleurs. Les deux versions ne décrivent pas de la même manière son propre rôle.','DEUX DOSSIERS FINANCIERS','La victime prévoyait un dossier public et un dossier complet pour les contrôleurs. Ils ne présentent pas son rôle de la même façon.'),
('019','A','v570_runtime_trames',2,'Une caméra coupée et un agent déplacé','La surveillance a été modifiée pendant l''interception du lanceur d''alerte. Les registres ne disent pas, à eux seuls, pourquoi le chef de sécurité a pris ces décisions.','SURVEILLANCE MODIFIÉE','La surveillance a changé pendant l’interception du lanceur d’alerte. Les registres n’expliquent pas les décisions du chef de sécurité.'),
('019','A','v570_runtime_trames',3,'De fausses prestations et des copies effacées','Les factures complètes révèlent des prestations de sécurité sans preuve de service rendu. D''autres documents ont été retirés après le décès, à la demande d''un service institutionnel.','FACTURES ET PIÈCES RETIRÉES','Des factures de sécurité ne prouvent aucun service rendu. Après le décès, un service institutionnel demande de retirer d’autres pièces.'),
('019','B','v570_runtime_trames',1,'Un entretien privé absent du programme','La victime devait parler publiquement. Un rendez-vous avec le mécène a été organisé à l''écart des invités. Cette rencontre n''apparaît pas dans le programme officiel.','RENDEZ-VOUS PRIVÉ AU GALA','La victime devait rencontrer le mécène à l’écart des invités. Ce rendez-vous était absent du programme officiel.'),
('019','B','v570_runtime_trames',3,'Un registre modifié après la mort','Une copie conservée du registre d''accès diffère de la version communiquée après le décès. Le changement concerne la rencontre privée et doit être confronté aux autres preuves.','DEUX VERSIONS DU REGISTRE','Deux copies du registre d’accès diffèrent sur la rencontre privée. L’une a été communiquée après le décès.'),
('019','C','v570_runtime_trames',1,'Deux versions, plusieurs signatures','La copie publique du dossier ne contient pas les mêmes annexes que le dossier intégral. Les documents manquants comportent des signatures de la victime et de responsables de la fondation.','ANNEXES SIGNÉES MANQUANTES','La copie publique du dossier manque des annexes signées par la victime et des responsables de la fondation.'),
('019','C','v570_runtime_trames',2,'Deux registres qui ne concordent pas','Le journal technique de sécurité et un relevé administratif n''attribuent pas le même passage à la même personne. Il faut vérifier lequel a été modifié.','REGISTRES CONTRADICTOIRES','Le registre de sécurité et le relevé administratif attribuent le même passage à deux personnes différentes. On ignore lequel a été modifié.'),
('020','A','v600_runtime_trames',1,'Des sorties sous restriction','Le plan indique plusieurs issues. Une note interne prévoit cependant des accès réservés aux équipes et aux mécènes, sans preuve qu''ils étaient prêts à laisser sortir la foule en urgence.','SORTIES SOUS RESTRICTION','Le plan prévoit plusieurs sorties, mais certaines sont réservées au personnel ou aux mécènes. Leur usage en urgence n’est pas confirmé.'),
('020','A','v600_runtime_trames',2,'Des vérifications restées incomplètes','Avant l''ouverture, des contrôles manquent sur certaines issues secondaires. Leurs responsables avaient pourtant reçu plusieurs avertissements.','CONTRÔLES INCOMPLETS','Des contrôles de sorties secondaires n’ont pas été faits malgré plusieurs avertissements aux responsables.'),
('020','A','v600_runtime_trames',3,'Une réparation toujours reportée','Un problème de protection incendie avait été signalé puis laissé sans réparation complète. Une vérification des portes a également été écourtée.','PROTECTION INCENDIE NON RÉPARÉE','Un dispositif contre l’incendie n’a pas été réparé complètement. La vérification des portes a aussi été écourtée.'),
('020','A','v600_runtime_trames',4,'Une alerte d''abord sous-estimée','Le poste reçoit d''abord un signal local, puis plusieurs alertes plus graves. Les heures permettent de vérifier quand une évacuation générale était nécessaire.','ALERTES DE PLUS EN PLUS GRAVES','Le poste de sécurité reçoit une première alerte locale, puis des alertes graves. L’évacuation générale n’est pas lancée aussitôt.'),
('020','A','v600_runtime_trames',5,'Le feu ne part pas tout seul','L''examen des traces montre un petit départ volontaire dans une zone de service. Il faut encore distinguer le geste initial des défauts ayant aggravé la catastrophe.','DÉPART DE FEU VOLONTAIRE','L’expertise relève un petit départ de feu volontaire. Des défauts de sécurité ont ensuite aggravé la catastrophe.'),
('020','A','v600_runtime_trames',6,'L''annonce générale arrive trop tard','Une première alerte n''a pas immédiatement conduit à faire sortir la salle. Des messages ultérieurs signalent un danger grave avant l''annonce finale.','ÉVACUATION RETARDÉE','Une première alerte n’entraîne pas l’évacuation. D’autres messages signalent un danger grave avant l’annonce au public.'),
('020','B','v600_runtime_trames',1,'Les portes prévues et les portes disponibles','Le plan montre des sorties possibles, mais leur fonctionnement n''a pas été vérifié dans la configuration du gala.','SORTIES NON VÉRIFIÉES','Le plan prévoit plusieurs sorties, mais leur fonctionnement réel le soir du gala n’avait pas été vérifié.'),
('020','B','v600_runtime_trames',2,'Le dernier contrôle a été annulé','La ronde finale des issues devait confirmer leur ouverture. Elle a été supprimée pour respecter le programme de la réception.','DERNIÈRE RONDE ANNULÉE','La dernière ronde destinée à vérifier les sorties a été annulée pour ne pas retarder le programme du gala.'),
('020','B','v600_runtime_trames',3,'Deux rapports sur la même installation','Une note technique mentionne une protection défaillante. Le document remis aux organisateurs affirme pourtant que les équipements sont prêts.','DEUX RAPPORTS CONTRADICTOIRES','Une note signale une protection défaillante. Le document remis aux organisateurs affirme pourtant que tout est prêt.'),
('020','B','v600_runtime_trames',4,'Une intrusion sans preuve d''incendie volontaire','Un activiste était près d''une zone de service, mais aucun témoin ne l''a vu allumer un feu ni manipuler l''installation à l''origine de la panne.','ACTIVISTE PRÈS DU SITE','Un activiste était près d’une zone de service, mais personne ne l’a vu allumer un feu ni provoquer la panne.'),
('020','B','v600_runtime_trames',5,'Une panne à l''origine du feu','L''expertise rattache le départ de feu à un dysfonctionnement accidentel. Les sorties et les protections insuffisantes ont ensuite aggravé ses effets.','FEU CAUSÉ PAR UNE PANNE','L’expertise relie le feu à une panne. Des sorties mal accessibles et des protections insuffisantes ont aggravé les conséquences.'),
('020','B','v600_runtime_trames',6,'Un rapport rassurant, puis des alarmes','Le coordinateur avait reçu un rapport favorable. Plusieurs alertes supplémentaires ont pourtant fini par montrer que la situation exigeait une évacuation.','RAPPORT RASSURANT, PUIS ALERTES','Le coordinateur avait reçu un rapport rassurant. Les alertes suivantes montraient pourtant qu’il fallait évacuer.'),
('020','C','v600_runtime_trames',1,'Un trajet réservé aux invités importants','Le plan distingue les sorties du public d''un couloir réservé aux VIP. Certains passages ordinaires offrent donc moins de possibilités lors d''une urgence.','COULOIR RÉSERVÉ AUX INVITÉS','Le plan sépare les sorties du public d’un couloir réservé aux invités importants. Cela réduit les passages accessibles en urgence.'),
('020','C','v600_runtime_trames',2,'Un spectacle ajouté au dernier moment','Un numéro scénique de clôture a été approuvé tardivement. Sa description complète n''apparaît pas dans le programme remis aux invités.','SPECTACLE AJOUTÉ TARDIVEMENT','Un spectacle de clôture a été approuvé tardivement. Sa description complète n’apparaît pas dans le programme remis aux invités.'),
('020','C','v600_runtime_trames',3,'Des protections encore insuffisantes','Une réserve de maintenance n''avait pas été levée lors de l''ajout de l''effet scénique. Le contrôle complet de ce nouveau risque manque au dossier.','SÉCURITÉ DU SPECTACLE INCOMPLÈTE','Un problème de sécurité n’avait pas été résolu avant l’ajout de l’effet de scène. Aucun contrôle complet du nouveau risque n’apparaît.'),
('020','C','v600_runtime_trames',4,'La fumée d''abord prise pour un effet','Plusieurs témoins pensent d''abord voir un élément du spectacle. D''autres messages avertissent qu''un véritable incendie se développe.','FUMÉE PRISE POUR UN EFFET','Des témoins pensent d’abord que la fumée fait partie du spectacle. D’autres messages signalent un véritable incendie.'),
('020','C','v600_runtime_trames',5,'Le numéro de clôture a déclenché le feu','Une copie du programme de production et l''analyse des traces relient le départ de feu à l''effet scénique autorisé. Elles n''établissent aucun sabotage de l''activiste.','EFFET DE SCÈNE À L’ORIGINE DU FEU','Le programme et l’expertise relient le départ du feu à l’effet de scène autorisé, sans preuve de sabotage par l’activiste.'),
('020','C','v600_runtime_trames',6,'Les VIP évacués avant les autres','Un avis urgent demandait une sortie générale. L''annonce au public a été repoussée pendant que la délégation passait par son couloir réservé.','INVITÉS ÉVACUÉS AVANT LE PUBLIC','Une évacuation générale était demandée, mais l’annonce au public a été repoussée pendant la sortie des invités importants.')
), changed_fields AS (
 SELECT m.scenario_id,m.variant_id,k.key,jsonb_agg(CASE WHEN e.scenario_id IS NOT NULL THEN jsonb_set(jsonb_set(t.item,'{title}',to_jsonb(e.new_title),true),'{text}',to_jsonb(e.new_text),true) ELSE t.item END ORDER BY t.ord) new_array,count(e.scenario_id) changes
 FROM igr_private.igr_v99_variant_manuscripts m CROSS JOIN LATERAL jsonb_each(m.manuscript) k(key,payload)
 CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN k.key~'_runtime_trames$' AND jsonb_typeof(k.payload)='array' THEN k.payload ELSE '[]'::jsonb END) WITH ORDINALITY t(item,ord)
 LEFT JOIN edits e ON e.scenario_id=m.scenario_id AND e.variant_id=m.variant_id AND e.field=k.key AND e.ord=t.ord AND e.old_title=t.item->>'title' AND e.old_text=t.item->>'text'
 WHERE m.scenario_id BETWEEN '018' AND '020' AND k.key~'_runtime_trames$' GROUP BY m.scenario_id,m.variant_id,k.key
), by_manuscript AS (SELECT scenario_id,variant_id,jsonb_object_agg(key,new_array) fields,sum(changes) changes FROM changed_fields GROUP BY scenario_id,variant_id), saved AS (
 UPDATE igr_private.igr_v99_variant_manuscripts m SET manuscript=m.manuscript||c.fields,updated_at=now() FROM by_manuscript c WHERE m.scenario_id=c.scenario_id AND m.variant_id=c.variant_id AND c.changes>0 RETURNING m.scenario_id,m.variant_id,c.changes
) SELECT count(*) changed_variants,coalesce(sum(changes),0) changed_trames FROM saved;
